    { "law_id": "graphite-total", "says": "Graphite is mined and consumed when leads are made.", "resource": "graphite", "may_change_by": ["mine-graphite", "make-leads"] },
    { "law_id": "clay-total", "says": "Clay is consumed when leads are made.", "resource": "clay", "may_change_by": ["make-leads"] },
    { "law_id": "leads-total", "says": "Leads are made from graphite and clay and consumed in pencil assembly.", "resource": "leads", "may_change_by": ["make-leads", "assemble-pencils"] },
    { "law_id": "pencils-total", "says": "Assembly makes pencils; packing and customer purchases change their form or use them.", "resource": "pencils", "may_change_by": ["assemble-pencils", "pack-pencils", "buy-pencil"] },
    { "law_id": "paint-total", "says": "Paint is consumed when pencils are assembled.", "resource": "paint", "may_change_by": ["assemble-pencils"] },
    { "law_id": "erasers-total", "says": "Erasers are consumed when pencils are assembled.", "resource": "erasers", "may_change_by": ["assemble-pencils"] },
    { "law_id": "ferrules-total", "says": "Ferrules are consumed when pencils are assembled.", "resource": "ferrules", "may_change_by": ["assemble-pencils"] },
    { "law_id": "boxes-total", "says": "Boxes are consumed when pencils are packed.", "resource": "boxes", "may_change_by": ["pack-pencils"] },
    { "law_id": "money-total", "says": "Cash changes hands only when a customer buys pencils.", "resource": "money", "may_change_by": ["buy-pencil"] }
  ],
  "not_modeled": [
    "Exact geographic routes and real travel time between the named regions."
  ]
