    },
    {
      "description": "Pack finished pencils into boxes.",
      "fields": [
        {
          "name": "quantity",
          "type": "integer"
        }
      ],
      "kind": "pack-pencils"
    },
    {
      "description": "Arrange for a quantity of boxed pencils to be delivered to a shop.",
