        }
      ],
      "kind": "book-pencil-shipment"
    },
    {
      "description": "Advance a booked pencil shipment toward its shop destination.",
      "fields": [],
      "kind": "deliver-pencil-shipment"
    },
    {
      "description": "A customer buys a pencil from a shop, paying the shop's listed price.",
      "fields": [
